```json
{
  "root_causes": [
    {
      "service": "ts-payment-service",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT CAST(date_trunc('minute', time) AS VARCHAR) t, ROUND(AVG(CASE WHEN metric='k8s.pod.cpu.usage' THEN value END),2) cpu, ROUND(MAX(CASE WHEN metric='k8s.pod.cpu_limit_utilization' THEN value END),2) cpulim FROM abnormal_metrics WHERE service_name='ts-payment-service' GROUP BY 1 ORDER BY 1",
          "claim": "Payment pod CPU jumped from about 0.01 cores to 1.9 cores average and up to 92% of its limit in the first minutes of the incident."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, COUNT(*) n, ROUND(AVG(value),2) avg_v, ROUND(MAX(value),2) max_v FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-payment%' GROUP BY 1,2",
          "claim": "ts-payment-service pod restart counter reached 1 during the incident; it was 0 in the normal period."
